import React, { useState, useRef, useEffect } from "react";
import * as styles from "./DraggableModal.module.css";

export default function DraggableModal({ isOpen, onClose, title = "blank", children, zIndex = 1000, onClick }) {
  const [visible, setVisible] = useState(isOpen);
  const [closing, setClosing] = useState(false);

  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [start, setStart] = useState(null);
  const headerRef = useRef(null);

  // Open / close animation
  useEffect(() => {
    if (isOpen) {
      setVisible(true);
      setClosing(false);
    } else {
      setClosing(true);
      setTimeout(() => setVisible(false), 150);
    }
  }, [isOpen]);

  if (!visible) return null;

  const onPointerDown = (e) => {
    if (e.target !== headerRef.current) return;
    e.preventDefault();
    e.target.setPointerCapture?.(e.pointerId);
    setStart({ x: e.clientX - pos.x, y: e.clientY - pos.y });
  };

  const onPointerMove = (e) => {
    if (!start) return;
    setPos({ x: e.clientX - start.x, y: e.clientY - start.y });
  };

  const onPointerUp = () => setStart(null);

  const triggerClose = () => {
    setClosing(true);
    setTimeout(() => onClose(), 150);
  };

  return (
    <div className={styles.overlay} style={{ zIndex }}>
      <div
        className={styles.dragWrapper}
        style={{ transform: `translate(${pos.x}px, ${pos.y}px)`, zIndex }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onClick={(e) => { e.stopPropagation(); if(onClick) onClick(); }}
      >
        <div className={`${styles.scaleWrapper} ${closing ? styles.scaleOut : ""}`}>
          <h3 ref={headerRef} className={styles.containerHeader}>
            {title}
            <span className={styles.containerHeaderclose} onClick={triggerClose}>x</span>
          </h3>
          <div className={styles.modalContent}>{children}</div>
        </div>
      </div>
    </div>
  );
}
